export function CardBody({
  heading = "{{heading}}",
  body = "{{body}}",
  density = "{{density}}",
  color = "{{color}}",
}) {
  return (
    <div style={{ font: "14px/1.55 system-ui, sans-serif", color: "#241430", borderLeft: "3px solid " + color, padding: density === "compact" ? 10 : 16, maxWidth: 300, background: "#FAF7F2" }}>
      <h3 style={{ margin: "0 0 6px", fontSize: 15 }}>{heading}</h3>
      <p style={{ margin: 0, fontSize: 13, opacity: 0.85 }}>{body}</p>
    </div>
  );
}
